SELECT hd_bill.hd_buy_potential AS bill_buy_potential, hd_ship.hd_buy_potential AS ship_buy_potential, sm.sm_ship_mode_id, COUNT(*) AS sales_count, SUM(cs.cs_net_profit) AS total_profit, AVG(cs.cs_net_profit) AS avg_profit, CASE WHEN AVG(cs.cs_net_profit) > 500 THEN 'HighAvgProfit' WHEN AVG(cs.cs_net_profit) BETWEEN 200 AND 500 THEN 'MidAvgProfit' ELSE 'LowAvgProfit' END AS profit_category, DENSE_RANK() OVER (ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_dense_rank FROM catalog_sales cs JOIN household_demographics hd_bill ON cs.cs_bill_hdemo_sk = hd_bill.hd_demo_sk JOIN household_demographics hd_ship ON cs.cs_ship_hdemo_sk = hd_ship.hd_demo_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY hd_bill.hd_buy_potential, hd_ship.hd_buy_potential, sm.sm_ship_mode_id HAVING COUNT(*) > 100 ORDER BY total_profit DESC LIMIT 15
